what-an-agent-is.code:
// The model is mocked as a policy: given observations, it emits the next action.
function agentLoop(policy, env, maxSteps = 10) {
  const trajectory = [];
  let obs = env.reset();
  for (let step = 0; step < maxSteps; step++) {
    const action = policy(obs, trajectory);      // "the model decides"
    trajectory.push({ step, action: action.tool, obs });
    if (action.tool === "finish") return { done: true, trajectory, answer: action.answer };
    obs = env.step(action);                        // "your code executes + observes"
  }
  return { done: false, trajectory, answer: null }; // ran out of budget
}

