observe-decide-act-loop.code:
function runCycle(decide, execute, seed, goalReached, maxSteps = 8) {
  let history = [...seed];
  const actions = [];
  for (let i = 0; i < maxSteps; i++) {
    const decision = decide(history);              // DECIDE from full history
    actions.push(decision.tool);
    if (decision.tool === "finish") return { history, actions, done: true };
    const result = execute(decision);              // ACT
    history = [...history,                          // ACCUMULATE (the memory)
      { role: "assistant", tool_use: decision },
      { role: "user", tool_result: result }];      // OBSERVE next turn
    if (goalReached(result)) history.push({ role: "system", note: "goal met" });
  }
  return { history, actions, done: false };
}

