planning-decomposition.code:
// tasks: { id: [deps...] }. Return an order where every task follows its deps.
function plan(tasks) {
  const order = [], done = new Set();
  const ready = () => Object.keys(tasks).filter(t => !done.has(t) && tasks[t].every(d => done.has(d)));
  while (done.size < Object.keys(tasks).length) {
    const next = ready().sort();               // deterministic tie-break
    if (next.length === 0) return { ok: false, reason: "cycle", order };  // stuck = cycle
    for (const t of next) { order.push(t); done.add(t); }
  }
  return { ok: true, order };
}

