react-pattern.code:
const trace = [
  "Thought: I need the user's city to get weather.",
  "Action: get_profile(user=42)",
  "Observation: {city: 'Oslo'}",
  "Thought: Now fetch the forecast for Oslo.",
  "Action: get_forecast(city='Oslo')",
  "Observation: {tempC: -3}",
].join("\n");

function parseReAct(raw) {
  const steps = [];
  let cur = {};
  for (const line of raw.split("\n")) {
    const [, tag, val] = line.match(/^(Thought|Action|Observation):\s*(.*)$/) || [];
    if (!tag) continue;
    cur[tag.toLowerCase()] = val;
    if (tag === "Observation") { steps.push(cur); cur = {}; }   // triple complete
  }
  return steps;
}

