stopping-conditions-budgets.code:
function runBudgeted(step, { maxSteps, maxCost }) {
  let steps = 0, cost = 0;
  while (true) {
    if (steps >= maxSteps) return { halted: "steps", steps, cost };   // loop guard
    if (cost >= maxCost)  return { halted: "cost", steps, cost };      // bill guard
    const r = step();                         // one agent turn
    steps++; cost += r.cost;
    if (r.done) return { halted: "goal", steps, cost };               // success
  }
}

