state-and-memory.code:
class Memory {
  constructor(goal) { this.goal = goal; this.facts = {}; this.transcript = []; }
  remember(k, v) { this.facts[k] = v; }            // distilled working memory
  append(turn) { this.transcript.push(turn); }
  compact(maxTurns) {                              // keep goal + recent, summarize rest
    if (this.transcript.length <= maxTurns) return;
    const recent = this.transcript.slice(-maxTurns);
    const dropped = this.transcript.length - recent.length;
    this.transcript = [{ role: "system", summary: `[${dropped} earlier turns summarized]` }, ...recent];
  }
}

