function classify(err) {
  if (/timeout|rate.?limit|unavailable|5\d\d/i.test(err)) return "transient";
  if (/invalid|validation|bad.?arg|missing|4\d\d/i.test(err)) return "permanent";
  if (/not.?found|empty|no results/i.test(err)) return "empty";
  return "unknown";
}
function recover(err, attempts, cap = 3) {
  const cls = classify(err);
  if (cls === "transient") return attempts < cap ? "retry" : "abort";  // bounded retry
  if (cls === "permanent") return "fix-args";      // retrying unchanged is pointless
  if (cls === "empty") return "try-alternative";   // valid signal, change approach
  return "abort";
}

