  const seen = new Set();
  return function check(step) {
    const fp = step.tool + "(" + JSON.stringify(step.args) + ")";   // action fingerprint
    if (seen.has(fp)) return { stuck: true, state: fp };            // exact repeat = no progress
    seen.add(fp);
    return { stuck: false };
  };
}

