argument-validation-bounding.code:
function validateAndBound(call, schema) {
  const errors = [];
  const inp = call.input || {};
  for (const req of schema.required || []) if (!(req in inp)) errors.push("missing " + req);
  for (const [k, spec] of Object.entries(schema.properties || {})) {
    if (!(k in inp)) continue;
    if (spec.type === "number" && typeof inp[k] !== "number") errors.push(k + " not a number");
    if (spec.enum && !spec.enum.includes(inp[k])) errors.push(k + " not in enum");
  }
  if (errors.length) return { ok: false, errors };
  const bounded = { ...inp };
  for (const [k, spec] of Object.entries(schema.properties || {}))   // clamp to safe bounds
    if (spec.type === "number" && typeof spec.max === "number") bounded[k] = Math.min(bounded[k], spec.max);
  return { ok: true, input: bounded };
}

