const RISK = {
  search: "low", read: "low",           // read-only → auto
  update: "medium",                      // reversible write
  delete: "high", send_email: "high", refund: "high",   // irreversible/costly → approve
};
function gate(action, approvalToken) {
  const risk = RISK[action.tool] || "high";       // unknown defaults to high (safe)
  if (risk === "low" || risk === "medium") return { execute: true };
  if (approvalToken === "APPROVED") return { execute: true, approved: true };
  return { execute: false, needsApproval: true, action };   // pause for a human
}

