multi-tool-workflows.code:
function runChain(steps, ctx = {}) {
  for (const s of steps) {
    const input = s.mapInput(ctx);           // build input from accumulated context
    const out = s.run(input);
    if (out.error) return { ok: false, failedAt: s.name, error: out.error, ctx };  // short-circuit
    ctx[s.name] = out.value;                  // thread output forward
  }
  return { ok: true, ctx };
}

