class Blackboard {
  constructor() { this.facts = {}; }
  read() { return { ...this.facts }; }               // everyone reads everything
  write(workerId, key, value) {
    const ns = workerId + "." + key;                 // namespaced by owner
    this.facts[ns] = value;                          // cannot clobber another worker's key
    return ns;
  }
}

