concurrency-and-races.code:
// NAIVE: each worker reads, adds, writes — interleaving loses updates.
function naive(state, deltas) {
  const snapshots = deltas.map(() => state.value);   // all read the SAME old value
  for (const d of deltas) state.value = snapshots.shift() + d;  // each writes old+delta
  return state.value;                                 // last writer wins → lost updates
}
// ATOMIC: the read-modify-write is one indivisible step per worker.
function atomic(state, deltas) {
  for (const d of deltas) state.value += d;           // no stale snapshot; each add sees the latest
  return state.value;
}

