evaluating-agent-trajectories.code:
function scoreTrajectory(log, rubric) {
  let score = 0; const notes = [];
  if (log.goalReached) { score += rubric.goal; notes.push("goal +" + rubric.goal); }
  const waste = Math.max(0, log.steps - rubric.optimalSteps);
  score -= waste * rubric.stepPenalty; if (waste) notes.push("waste -" + waste * rubric.stepPenalty);
  score -= log.repeats * rubric.repeatPenalty;
  const bad = log.toolsUsed.filter(t => !rubric.allowedTools.includes(t));
  score -= bad.length * rubric.disallowedPenalty; if (bad.length) notes.push("disallowed " + bad.join(","));
  return { score, notes };
}

