capstone-bounded-guardrailed-agent.code:
const grant = { search: ["read"], send_email: ["write"], finish: ["read"] };  // least privilege
const GATED = new Set(["send_email"]);                          // high-impact: ask a human
function authorize(a) { return !!grant[a.tool]; }
function validate(a) {                                          // bound the arguments
  if (a.tool === "search") return typeof a.args.q === "string" && a.args.q.length <= 64;
  return true;
}
function runAgent(policy, env, budget, approve) {
  const log = { turns: 0, steps: 0, repeats: 0, toolsUsed: [], goalReached: false,
                denied: [], invalid: [], gated: [] };
  const seen = new Set();
  while (log.turns < budget.maxTurns) {          // the budget bounds TURNS, not successes
    log.turns++;                                 // spent at the TOP: no branch below can skip it
    const a = policy(env.observe(), log);
    if (!authorize(a)) { log.denied.push(a.tool); continue; }   // deny BEFORE execution
    if (!validate(a)) { log.invalid.push(a.tool); continue; }   // out-of-bounds arguments
    const fp = a.tool + JSON.stringify(a.args || {});
    if (seen.has(fp)) { log.repeats++; break; }                 // loop guard
    seen.add(fp);
    if (GATED.has(a.tool)) {                                    // human-in-the-loop
      log.gated.push(a.tool);
      if (!approve(a)) continue;                                // declined -> never runs
    }
    log.steps++; log.toolsUsed.push(a.tool);
    if (a.tool === "finish") { log.goalReached = true; break; }
    env.step(a);
  }
  return log;
}

